from hermes_tools import terminal
r=terminal("python3 - <<'PY'
# Candidate packing inferred from demo: color 2 left, color 3 right;
# upper components bottom-align at row 6, lower at row 9; one-column gap.
objects = [
 (2, {(1,0),(1,1),(1,2),(1,3),(2,3),(3,2),(3,3)}, 'top-left'),
 (3, {(1,6),(1,7),(1,8)}, 'top-right'),
 (2, {(r,c) for r in (6,7) for c in (6,7,8)}, 'bottom-left'),
 (3, {(5,3),(5,4),(6,1),(6,2),(6,3),(6,4),(7,3)}, 'bottom-right'),
]
grid=[[0]*10 for _ in range(10)]
# row order pairs; place first object at col 0, second after its bbox width + one gap
for k in (0,2):
    a, b = objects[k], objects[k+1]
    ca, pa, _ = a; cb, pb, _ = b
    ar0=min(r for r,c in pa); ar1=max(r for r,c in pa); ac0=min(c for r,c in pa); ac1=max(c for r,c in pa)
    br0=min(r for r,c in pb); br1=max(r for r,c in pb); bc0=min(c for r,c in pb); bc1=max(c for r,c in pb)
    base = 6 if k == 0 else 9
    apos={(base-(ar1-ar0)+(r-ar0), c-ac0) for r,c in pa}
    bcol=(ac1-ac0+1)+1
    bpos={(base-(br1-br0)+(r-br0), bcol+(c-bc0)) for r,c in pb}
    for color, pts in ((ca,apos),(cb,bpos)):
        for r,c in pts:
            if not (0<=r<10 and 0<=c<10): raise ValueError((r,c))
            if grid[r][c] != 0: raise ValueError(('overlap',r,c))
            grid[r][c]=color
for row in grid: print(''.join(map(str,row)))
PY")
print(r.get('output',''))

